// ── source: vcx/tests/net_set_deadline_test.v ──
// net_set_deadline_test.v — #29 (fail-loud slice): net:set-deadline /
// net:set-opt are socket operations. Called on a `[std-stream …]` handle
// (stdin/stdout/stderr from cx-stdlib/env) they were SILENTLY accepted yet had
// no effect — a read still blocked past the "deadline". They must now reject
// loudly (CXER4522) so the caller learns it immediately. (A timeout / non-
// blocking std-stream READ is a separate, not-yet-available surface.)

fn cx_bin_dl() string {
	return testenv.cx_bin()
}

fn run_dl(prog_body string) os.Result {
	path := os.join_path(os.temp_dir(), 'cx_dl29_${os.getpid()}.cx')
	os.write_file(path, prog_body) or { panic(err) }
	defer { os.rm(path) or {} }
	return os.execute('${cx_bin_dl()} --allow-env --allow-net ${path}')
}

// set-deadline on stdin (a std-stream) must be rejected, not silently accepted.
fn test_set_deadline_on_stdin_rejects() {
	r := run_dl("[?lib 'cx-stdlib/env' :as env]\n[?lib 'cx-stdlib/net' :as net]\n" +
		'[?let [= \$in [\$env:stdin]] [\$net:set-deadline \$in {read: 500ms}]]\n')
	assert r.output.contains('CXER4522'), 'set-deadline on stdin should reject (CXER4522): ${r.output}'
	assert r.output.contains('std-stream'), 'denial should name the std-stream handle: ${r.output}'
}

// set-opt on a std-stream is likewise rejected (same socket-op rule).
fn test_set_opt_on_stdout_rejects() {
	r := run_dl("[?lib 'cx-stdlib/env' :as env]\n[?lib 'cx-stdlib/net' :as net]\n" +
		'[?let [= \$out [\$env:stdout]] [\$net:set-opt \$out {nodelay: true}]]\n')
	assert r.output.contains('CXER4522'), 'set-opt on stdout should reject (CXER4522): ${r.output}'
}

// ── source: vcx/tests/net_set_opt_test.v ──
// net_set_opt_test.v — BEHAVIORAL gate for #548: `[$net:set-opt]` either
// APPLIES a §3.7 option or REFUSES it loudly, per key — never a phantom
// accept (before the fix every option except the #56 deadlines was
// silently swallowed). Availability per this build's V net surface:
// line-terminator / keepalive / recv-buf / send-buf / nodelay=true apply;
// nodelay=false, linger, multicast-*, unknown keys, and cross-transport
// misuse (broadcast on TCP) refuse with E_NET_ARG_INVALID naming the
// option. UDP broadcast applies.

fn nso_pick_port() int {
	salt := (u64(os.getpid()) * u64(2654435761) + u64(time.now().unix_nano())) % 80
	return 26200 + int(salt)
}

fn test_set_opt_applies_or_refuses_per_key() {
	port := nso_pick_port()
	mut listener := net.listen_tcp(.ip, '127.0.0.1:${port}') or {
		eprintln('SKIP: cannot bind 127.0.0.1:${port}: ${err}')
		return
	}
	listener.set_accept_timeout(10 * time.second)
	srv := spawn fn (mut l net.TcpListener) {
		mut c := l.accept() or {
			l.close() or {}
			return
		}
		time.sleep(3000 * time.millisecond)
		c.close() or {}
		l.close() or {}
	}(mut listener)

	prog := os.join_path(os.temp_dir(), 'nso-${os.getpid()}.cx')
	os.write_file(prog, "[?lib 'cx-stdlib/net' :as net]
[?let
  [= \$s [\$net:dial-tcp 'tcp://127.0.0.1:${port}' {read-deadline: 1000}]]
  [= \$u [\$net:dial-udp 'udp://127.0.0.1:${port}' {}]]
  ([applies ([\$net:set-opt \$s {line-terminator: 'crlf'}],
             [\$net:set-opt \$s {keepalive: true}],
             [\$net:set-opt \$s {keepalive: 30000}],
             [\$net:set-opt \$s {recv-buf: 65536, send-buf: 65536}],
             [\$net:set-opt \$s {nodelay: true}],
             [\$net:set-opt \$u {broadcast: true}])],
   [\$net:set-opt \$s {nodelay: false}],
   [\$net:set-opt \$s {linger: 5}],
   [\$net:set-opt \$s {broadcast: true}],
   [\$net:set-opt \$u {multicast-ttl: 4}],
   [\$net:set-opt \$s {frobnicate: 1}])]
") or { panic(err) }
	defer {
		os.rm(prog) or {}
	}
	res := os.execute('${testenv.cx_bin()} --allow-net=127.0.0.1:${port} ${prog}')
	srv.wait()
	assert res.exit_code == 0, 'program failed: ${res.output}'
	out := res.output
	// #853 — each refusal is a computed [err], and an err in element CHILD
	// position now propagates (code.md §6.4.1), so the per-refusal `[label …]`
	// wrappers would short-circuit to bare errs and take their labels with
	// them. The refusals sit directly in the paren SEQUENCE instead — a
	// sequence is not element construction and does not propagate — while
	// `[applies …]` keeps its wrapper because every option in it succeeds.
	//
	// The applying group is now asserted EXACTLY rather than as "contains no
	// [err] and contains six nulls", which is a stronger check than the two it
	// replaces.
	assert out.contains('[applies (null, null, null, null, null, null)]'),
		'the six applying options must all yield null: ${out}'
	// each refusal names its option
	assert out.contains('nodelay=false cannot be applied'), 'nodelay=false: ${out}'
	assert out.contains('linger is not settable'), 'linger: ${out}'
	assert out.contains('broadcast is a UDP option'), 'broadcast-on-tcp: ${out}'
	assert out.contains('multicast-ttl is not settable'), 'multicast: ${out}'
	assert out.contains('unknown socket option "frobnicate"'), 'unknown key: ${out}'
}

// ── source: vcx/tests/net_stream_iter_test.v ──
// net_stream_iter_test.v — BEHAVIORAL conformance for §3.4 stream iterators:
// line-iter yields CRLF/LF-stripped lines off a socket until EOF; chunk-iter
// yields fixed-size byte chunks. A V server pushes a few lines then closes; a cx
// client dials, walks the iterator with [?for], and collects the lines.

fn cx_binary() string {
	return testenv.cx_bin()
}

// Disjoint PID + nanosecond-salted band (26800-26899) so the concurrent
// `v test vcx/tests/` gate processes don't collide on a port.
fn pick_port() int {
	salt := (u64(os.getpid()) * u64(2654435761) + u64(time.now().unix_nano())) % 100
	return 26800 + int(salt)
}

fn write_tmp(name string, content string) string {
	p := os.join_path(os.temp_dir(), name)
	os.write_file(p, content) or { panic('write ${p}: ${err}') }
	return p
}

fn test_net_line_iter() {
	port := pick_port()
	mut l := net.listen_tcp(.ip, '127.0.0.1:${port}') or {
		eprintln('SKIP: cannot bind ${port}: ${err}')
		return
	}
	l.set_accept_timeout(5 * time.second)
	srv := spawn fn (mut l net.TcpListener) {
		mut c := l.accept() or {
			l.close() or {}
			return
		}
		c.write_string('alpha\nbravo\ncharlie\n') or {}
		c.close() or {} // EOF terminates the iterator
		l.close() or {}
	}(mut l)

	// cx client: dial, walk line-iter, yield each line joined.
	prog := write_tmp('cx_lineiter.cx', '[?lib \'cx-stdlib/net\' :as net]\n' +
		'[?let [= \$s [\$net:dial-tcp "tcp://127.0.0.1:${port}" {}]]\n' +
		'  [?for [in \$ln [\$net:line-iter \$s]]\n' +
		'    [yield \$ln]]]\n')
	res := os.execute('${cx_binary()} --allow-net=127.0.0.1:${port} ${prog}')
	srv.wait()
	out := res.output
	assert out.contains('alpha'), 'line-iter missed alpha; got: ${out}'
	assert out.contains('bravo'), 'line-iter missed bravo; got: ${out}'
	assert out.contains('charlie'), 'line-iter missed charlie; got: ${out}'
}

fn test_net_chunk_iter() {
	port := pick_port() + 30
	mut l := net.listen_tcp(.ip, '127.0.0.1:${port}') or {
		eprintln('SKIP: cannot bind ${port}: ${err}')
		return
	}
	l.set_accept_timeout(5 * time.second)
	srv := spawn fn (mut l net.TcpListener) {
		mut c := l.accept() or {
			l.close() or {}
			return
		}
		c.write_string('0123456789ABCDE') or {} // 15 bytes → chunks of 4 + a tail
		c.close() or {}
		l.close() or {}
	}(mut l)

	// walk chunk-iter (size 4) and count the chunks: ceil(15/4) = 4.
	prog := write_tmp('cx_chunkiter.cx', '[?lib \'cx-stdlib/net\' :as net]\n' +
		'[?lib \'cx-stdlib/bytes\' :as bytes]\n' +
		'[?let [= \$s [\$net:dial-tcp "tcp://127.0.0.1:${port}" {}]]\n' +
		'  [\$count [?for [in \$ck [\$net:chunk-iter \$s 4]]\n' +
		'    [yield [\$bytes:to-string-latin1 \$ck]]]]]\n')
	res := os.execute('${cx_binary()} --allow-net=127.0.0.1:${port} ${prog}')
	srv.wait()
	out := res.output.trim_space()
	assert out == '4', 'chunk-iter did not yield 4 chunks for 15 bytes @ size 4; got: ${out}'
}

// ── source: vcx/tests/net_tls_test.v ──
// net_tls_test.v — BEHAVIORAL conformance for cx-stdlib/net TLS client core
// (net.md §3.6): [$net:dial-tls] performs a REAL mbedTLS handshake over a real
// TCP connection and the §3.4 stream verbs work over the secured socket. Backed
// by an in-process mbedTLS TLS echo server with a throwaway self-signed cert.
// Skipped only when openssl (cert gen) is unavailable. MUST fail against a stub.

fn test_net_dial_tls_roundtrip() {
	if os.execute('which openssl').exit_code != 0 {
		eprintln('SKIP: openssl not available (cert generation)')
		return
	}
	// Disjoint PID + nanosecond-salted slot (27500-27599) so the concurrent
	// `v test vcx/tests/` gate processes don't collide on a port.
	salt := (u64(os.getpid()) * u64(2654435761) + u64(time.now().unix_nano())) % 100
	port := 27500 + int(salt)
	dir := os.temp_dir()
	cert := os.join_path(dir, 'cx_tls_cert.pem')
	key := os.join_path(dir, 'cx_tls_key.pem')
	gen := os.execute('openssl req -x509 -newkey rsa:2048 -keyout ${key} -out ${cert} -days 1 -nodes -subj "/CN=localhost" 2>/dev/null')
	if gen.exit_code != 0 || !os.is_file(cert) {
		eprintln('SKIP: openssl self-signed cert generation failed')
		return
	}
	cfg := mbedtls.SSLConnectConfig{
		cert:     cert
		cert_key: key
		validate: false
	}
	mut l := mbedtls.new_ssl_listener('127.0.0.1:${port}', cfg) or {
		eprintln('SKIP: mbedtls TLS listen failed: ${err}')
		return
	}
	srv := spawn fn (mut l mbedtls.SSLListener) {
		mut c := l.accept() or {
			l.shutdown() or {}
			return
		}
		mut buf := []u8{len: 256}
		n := c.read(mut buf) or { 0 }
		if n > 0 {
			c.write(buf[..n]) or {}
		}
		c.shutdown() or {}
		l.shutdown() or {}
	}(mut l)

	prog := os.join_path(dir, 'cx_tls_client.cx')
	os.write_file(prog, '[?lib \'cx-stdlib/net\' :as net]\n' +
		'[?let [= \$s [\$net:dial-tls "tls://127.0.0.1:${port}" {tls: {verify: false}}]]\n' +
		'[?let [= \$w [\$net:write-line \$s "tls-ping"]]\n' +
		'[?let [= \$line [\$net:read-line \$s]]\n' +
		'[?let [= \$c [\$net:close \$s]]\n' + '  \$line]]]]\n') or { panic(err) }

	res := os.execute('${cx_binary()} --allow-net=127.0.0.1:${port} ${prog}')
	srv.wait()
	out := res.output.trim_space()
	assert out == "'tls-ping'", 'cx dial-tls did not round-trip over real TLS; got: ${out}'
}

// the http CLIENT over https:// — real TLS handshake + HTTP/1.1 over the secured
// socket (verify:false against a self-signed loopback origin, the §3.6 dev opt).
fn test_http_client_https_real() {
	if os.execute('which openssl').exit_code != 0 {
		eprintln('SKIP: openssl not available (cert generation)')
		return
	}
	// Disjoint PID + nanosecond-salted slot (27620-27719) so the concurrent
	// `v test vcx/tests/` gate processes don't collide on a port.
	salt := (u64(os.getpid()) * u64(2654435761) + u64(time.now().unix_nano())) % 100
	port := 27620 + int(salt)
	dir := os.temp_dir()
	cert := os.join_path(dir, 'cx_https_cert.pem')
	key := os.join_path(dir, 'cx_https_key.pem')
	gen := os.execute('openssl req -x509 -newkey rsa:2048 -keyout ${key} -out ${cert} -days 1 -nodes -subj "/CN=localhost" 2>/dev/null')
	if gen.exit_code != 0 || !os.is_file(cert) {
		eprintln('SKIP: openssl self-signed cert generation failed')
		return
	}
	cfg := mbedtls.SSLConnectConfig{
		cert:     cert
		cert_key: key
		validate: false
	}
	mut l := mbedtls.new_ssl_listener('127.0.0.1:${port}', cfg) or {
		eprintln('SKIP: mbedtls TLS listen failed: ${err}')
		return
	}
	srv := spawn fn (mut l mbedtls.SSLListener) {
		mut c := l.accept() or {
			l.shutdown() or {}
			return
		}
		mut buf := []u8{len: 4096}
		c.read(mut buf) or {}
		body := 'hello-https'
		resp := 'HTTP/1.1 200 OK\r\nContent-Length: ${body.len}\r\nContent-Type: text/plain\r\nConnection: close\r\n\r\n${body}'
		c.write(resp.bytes()) or {}
		c.shutdown() or {}
		l.shutdown() or {}
	}(mut l)

	prog := os.join_path(dir, 'cx_https_client.cx')
	os.write_file(prog, '[?lib \'cx-stdlib/http\' :as http]\n' +
		'[?let [= \$r [\$http:get "https://127.0.0.1:${port}/" {verify: false}]]\n' +
		'  [\$http:body-text \$r]]\n') or { panic(err) }

	res := os.execute('${cx_binary()} --allow-net=127.0.0.1:${port} ${prog}')
	srv.wait()
	out := res.output.trim_space()
	assert out == "'hello-https'", 'cx https client did not read the real TLS response body; got: ${out}'
}

// the cx TLS SERVER core (net.md §3.3/§3.6): [$net:listen-tls] binds a real
// mbedTLS listener (server cert/key from opts.tls), [$net:accept] does the
// per-peer handshake and yields a secure socket. A V mbedTLS client drives it.
fn test_net_listen_tls_roundtrip() {
	if os.execute('which openssl').exit_code != 0 {
		eprintln('SKIP: openssl not available (cert generation)')
		return
	}
	// Disjoint PID + nanosecond-salted slot (27740-27839) so the concurrent
	// `v test vcx/tests/` gate processes don't collide on a port.
	salt := (u64(os.getpid()) * u64(2654435761) + u64(time.now().unix_nano())) % 100
	port := 27740 + int(salt)
	dir := os.temp_dir()
	cert := os.join_path(dir, 'cx_tlssrv_cert.pem')
	key := os.join_path(dir, 'cx_tlssrv_key.pem')
	gen := os.execute('openssl req -x509 -newkey rsa:2048 -keyout ${key} -out ${cert} -days 1 -nodes -subj "/CN=localhost" 2>/dev/null')
	if gen.exit_code != 0 || !os.is_file(cert) {
		eprintln('SKIP: openssl self-signed cert generation failed')
		return
	}
	prog := os.join_path(dir, 'cx_tls_server.cx')
	os.write_file(prog, '[?lib \'cx-stdlib/net\' :as net]\n' +
		'[?let [= \$l [\$net:listen-tls "tls://127.0.0.1:${port}" {tls: {cert: "${cert}" key: "${key}"}}]]\n' +
		'[?let [= \$conn [\$net:accept \$l]]\n' +
		'[?let [= \$line [\$net:read-line \$conn]]\n' +
		'[?let [= \$w [\$net:write-line \$conn \$line]]\n' +
		'[?let [= \$cc [\$net:close \$conn]]\n' + '  [\$net:close \$l]]]]]]\n') or { panic(err) }

	pid_s := os.execute('${cx_binary()} --allow-net ${prog} >/tmp/cx-tlssrv.${port}.out 2>&1 & echo \$!')
	if pid_s.exit_code != 0 {
		eprintln('SKIP: could not spawn cx tls server')
		return
	}
	pid := pid_s.output.trim_space().int()
	defer {
		os.execute('kill ${pid} 2>/dev/null')
	}
	mut got := ''
	for _ in 0 .. 40 {
		mut c := mbedtls.new_ssl_conn(mbedtls.SSLConnectConfig{ validate: false }) or {
			time.sleep(100 * time.millisecond)
			continue
		}
		c.dial('127.0.0.1', port) or {
			time.sleep(100 * time.millisecond)
			continue
		}
		c.write_string('hello-tls-server\n') or {}
		mut buf := []u8{len: 256}
		n := c.read(mut buf) or { 0 }
		c.close() or {}
		got = buf[..n].bytestr().trim_space()
		break
	}
	assert got == 'hello-tls-server', 'cx tls server did not echo over a real TLS handshake; got: ${got}'
}

// ── source: vcx/tests/net_ssrf_test.v ──
// net_ssrf_test.v — the §4.5 SSRF / DNS-rebinding CORE: the pure
// canonicalize + deny-set classifier the dial/send-to guard composes. These
// vectors pin the mandatory deny set (loopback/link-local/private/CGNAT/ULA/
// this-host) and the canonicalization that defeats ::ffff: bypass (rev-4 M8).

fn test_ssrf_deny_set_ipv4() {
	// denied ranges
	for ip in ['127.0.0.1', '127.5.5.5', '10.0.0.5', '172.16.0.1', '172.31.255.1',
		'192.168.1.1', '169.254.169.254', '100.64.0.1', '100.127.0.1', '0.0.0.0'] {
		assert code.net_ip_in_deny_set(ip), 'expected ${ip} in deny set'
	}
	// allowed (public) — must NOT be denied
	for ip in ['8.8.8.8', '1.2.3.4', '172.15.0.1', '172.32.0.1', '100.63.0.1',
		'100.128.0.1', '93.184.216.34'] {
		assert !code.net_ip_in_deny_set(ip), 'expected ${ip} allowed (not in deny set)'
	}
}

fn test_ssrf_deny_set_ipv6() {
	for ip in ['::1', '::', 'fe80::1', 'febf::1', 'fc00::1', 'fd12:3456::1'] {
		assert code.net_ip_in_deny_set(ip), 'expected ${ip} in deny set'
	}
	for ip in ['2001:4860:4860::8888', '2606:4700::1111'] {
		assert !code.net_ip_in_deny_set(ip), 'expected ${ip} allowed'
	}
}

fn test_ssrf_canonicalization() {
	// IPv4-mapped IPv6 must unwrap so it classifies as the embedded IPv4
	assert code.net_canonicalize_ip('::ffff:169.254.169.254') == '169.254.169.254'
	assert code.net_ip_in_deny_set('::ffff:169.254.169.254'), 'mapped metadata IP must be denied'
	assert code.net_ip_in_deny_set('::ffff:10.0.0.5'), 'mapped private IP must be denied'
	assert !code.net_ip_in_deny_set('::ffff:8.8.8.8'), 'mapped public IP must be allowed'
	// zone id + brackets stripped
	assert code.net_canonicalize_ip('169.254.169.254%en0') == '169.254.169.254'
	assert code.net_canonicalize_ip('[::1]') == '::1'
}
